//! Raw FFI bindings to llama.cpp, generated by `build.rs` (bindgen) against a
//! freshly-built, up-to-date llama.cpp. We deliberately do NOT depend on any
//! external llama.cpp wrapper crate — those pin an old vendored llama.cpp that
//! (e.g.) mis-runs MiniCPM5. This crate always builds the LATEST llama.cpp
//! master (or a tree pointed to by `LLAMA_CPP_DIR`).
//!
//! Safe wrappers live in `tokenade-cli` (`agent::local`); this crate is the raw
//! `unsafe` surface only.
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
